import '../models/feeder_models.dart';
import 'feeder_service.dart';

/// Alerts are now generated by the Raspberry Pi (it is always running, the
/// app is not) and stored under devices/feeder01/alerts:
///   - high temperature
///   - water reservoir empty / bowl water low
///   - food hopper empty (dispense timed out)
///   - unrecognised or unregistered animal at the feeder
///   - feeder (ESP32) went offline
///
/// This class only exposes convenient views of that list for the UI.
class NotificationService {
  NotificationService._();
  static final NotificationService instance = NotificationService._();

  Stream<List<AlertItem>> alerts() => FeederService.instance.alertsStream();

  Stream<int> unreadCount() =>
      alerts().map((list) => list.where((a) => !a.read).length);

  Future<void> markRead(AlertItem a) => FeederService.instance.markAlertRead(a.id);

  Future<void> markAllRead(List<AlertItem> list) =>
      FeederService.instance.markAllAlertsRead(list);

  Future<void> clearAll() => FeederService.instance.clearAlerts();
}
